export default{tech_fiel_preview_extend_view:{type:"append",selector:{attr:"id",value:"template-meta-page-app"},view:{type:"page",id:"techFilePreview",dataSource:{filePath:"",fileType:"",fileId:"",filePrefix:"",placement:""},ds_config:{list:[{name:"getFiles",type:"meta",method:"service",autoRequest:!1,options:{params:{app:"base",args:{},context:{lang:"zh_CN",uid:""},model:"meta_attachment",service:"getFiles",tag:"master"}}}]},created:async e=>{let t=new URL(window.location.href),i=new URLSearchParams(t.search);if(["filePath","fileType","fileId","filePrefix","placement"].forEach(t=>{let a=decodeURIComponent(i.get(t)||"");e.$ds[t]=a}),e.$ds.filePath||e.$ds.fileId){if(!e.$ds.filePath&&e.$ds.fileId){const t=await e.request("getFiles",{args:{ids:[e.$ds.fileId]}});if(t.data){const i="/"+t.data[0].bucket+"/"+t.data[0].key;let a=e.$ds.filePrefix?e.$ds.filePrefix+i:i;e.$ds.filePath=a.replace(/^\/?/,"/")}else window.ELEMENT.Message("请求参数错误，未获取到文件地址！")}}else window.ELEMENT.Message("文件ID和文件地址为空，无法加载文件！")},items:[{type:"container",items:[{id:"tech-file-preView",type:"office-view",name:"preview",bind_fileType:"$ds.fileType",bind_src:"$ds.filePath",mounted:e=>{if("center"===e.$ds.placement){const e=document.getElementById("techFilePreview").parentNode;e.style.display="flex",e.style.justifyContent="center",e.style.alignItems="center"}}}]}]}}};